   194              } else {
   195                  if (stream->state < H2O_HTTP2_STREAM_STATE_SEND_HEADERS) {
   196                      h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_REQ_PENDING);
   197                      h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_SEND_HEADERS);
   198                  }
   199              }
   200
   201              h2o_linklist_unlink(&stream->_refs.link);
   202              ran_one_request = 1;
   203
   204              /* handle it */
   205              if (!h2o_http2_stream_is_push(stream->stream_id) && conn->pull_stream_ids.max_processed < stream->stream_id)
   206                  conn->pull_stream_ids.max_processed = stream->stream_id;
   207              h2o_process_request(&stream->req);
   208          }
   209
   210      } while (ran_one_request && !h2o_linklist_is_empty(&conn->_pending_reqs));
   211  }
   212
   213  static void execute_or_enqueue_request(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream)
   214  {
   215      assert(stream->state < H2O_HTTP2_STREAM_STATE_REQ_PENDING);
   216
   217      if (stream->req._write_req_chunk_done == NULL && stream->_req_body.body != NULL &&
   218          stream->req.content_length != SIZE_MAX && stream->_req_body.body->size != stream->req.content_length) {
   219          stream_send_error(conn, stream->stream_id, H2O_HTTP2_ERROR_PROTOCOL);
   220          h2o_http2_stream_reset(conn, stream);
   221          return;
   222      }
   223
   224      if (stream->req._write_req_chunk_done == NULL) {
   225          h2o_http2_stream_set_response_blocked_by_server(conn, stream, 1);
   226          h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_REQ_PENDING);
   227      }
   228
   229      /* TODO schedule the pending reqs using the scheduler */
   230      h2o_linklist_insert(&conn->_pending_reqs, &stream->_refs.link);
   231
   232      run_pending_requests(conn);
   233      update_idle_timeout(conn);
   234  }
   235
   236  void h2o_http2_conn_register_stream(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream)
   237  {
   238      khiter_t iter;
   239      int r;
   240
   241      iter = kh_put(h2o_http2_stream_t, conn->streams, stream->stream_id, &r);
   242      assert(iter != kh_end(conn->streams));
   243      kh_val(conn->streams, iter) = stream;
   244  }
   245
   246  void h2o_http2_conn_unregister_stream(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream)
   247  {
   248      khiter_t iter = kh_get(h2o_http2_stream_t, conn->streams, stream->stream_id);
   249      assert(iter != kh_end(conn->streams));
   250      kh_del(h2o_http2_stream_t, conn->streams, iter);
   251
   252      assert(h2o_http2_scheduler_is_open(&stream->_refs.scheduler));
   253      h2o_http2_scheduler_close(&stream->_refs.scheduler);
   254
   255      if (stream->_conn_stream_in_progress) {
   256          h2o_http2_conn_t *conn = (h2o_http2_conn_t *)stream->req.conn;
   257          stream->_conn_stream_in_progress = 0;
   258          conn->num_streams._request_body_in_progress--;
   259      }
   260
   261      switch (stream->state) {
   262      case H2O_HTTP2_STREAM_STATE_RECV_BODY:
   263          if (h2o_linklist_is_linked(&stream->_refs.link))
   264              h2o_linklist_unlink(&stream->_refs.link);
   265      /* fallthru */
   266      case H2O_HTTP2_STREAM_STATE_IDLE:
   267      case H2O_HTTP2_STREAM_STATE_RECV_HEADERS:
   268          assert(!h2o_linklist_is_linked(&stream->_refs.link));
   269          break;
   270      case H2O_HTTP2_STREAM_STATE_REQ_PENDING:
   271          assert(h2o_linklist_is_linked(&stream->_refs.link));
   272          h2o_linklist_unlink(&stream->_refs.link);
   273          break;
   274      case H2O_HTTP2_STREAM_STATE_SEND_HEADERS:
   275      case H2O_HTTP2_STREAM_STATE_SEND_BODY:
   276      case H2O_HTTP2_STREAM_STATE_SEND_BODY_IS_FINAL:
   277      case H2O_HTTP2_STREAM_STATE_END_STREAM:
   278          if (h2o_linklist_is_linked(&stream->_refs.link))
   279              h2o_linklist_unlink(&stream->_refs.link);
   280          break;
   281      }
   282      if (stream->state != H2O_HTTP2_STREAM_STATE_END_STREAM)
   283          h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_END_STREAM);
   284
   285      if (conn->state < H2O_HTTP2_CONN_STATE_IS_CLOSING) {
   286          run_pending_requests(conn);
   287          update_idle_timeout(conn);
   288      }
   289  }
   290
   291  static void close_connection_now(h2o_http2_conn_t *conn)
   292  {
   293      h2o_http2_stream_t *stream;
   294
   295      assert(!h2o_timeout_is_linked(&conn->_write.timeout_entry));
   296
   297      kh_foreach_value(conn->streams, stream, { h2o_http2_stream_close(conn, stream); });
   298
   299      assert(conn->num_streams.pull.open == 0);
   300      assert(conn->num_streams.pull.half_closed == 0);
   301      assert(conn->num_streams.pull.send_body == 0);
   302      assert(conn->num_streams.push.half_closed == 0);
   303      assert(conn->num_streams.push.send_body == 0);
   304      assert(conn->num_streams.priority.open == 0);
   305      kh_destroy(h2o_http2_stream_t, conn->streams);
   306      assert(conn->_http1_req_input == NULL);
   307      h2o_hpack_dispose_header_table(&conn->_input_header_table);
   308      h2o_hpack_dispose_header_table(&conn->_output_header_table);
   309      assert(h2o_linklist_is_empty(&conn->_pending_reqs));
   310      h2o_timeout_unlink(&conn->_timeout_entry);
   311      h2o_buffer_dispose(&conn->_write.buf);
   312      if (conn->_write.buf_in_flight != NULL)
   313          h2o_buffer_dispose(&conn->_write.buf_in_flight);
   314      h2o_http2_scheduler_dispose(&conn->scheduler);
   315      assert(h2o_linklist_is_empty(&conn->_write.streams_to_proceed));
   316      assert(!h2o_timeout_is_linked(&conn->_write.timeout_entry));
   317      if (conn->_headers_unparsed != NULL)
   318          h2o_buffer_dispose(&conn->_headers_unparsed);
   319      if (conn->push_memo != NULL)
   320          h2o_cache_destroy(conn->push_memo);
   321      if (conn->casper != NULL)
   322          h2o_http2_casper_destroy(conn->casper);
   323      h2o_linklist_unlink(&conn->_conns);
   324
   325      if (conn->sock != NULL)
   326          h2o_socket_close(conn->sock);
   327      free(conn);
   328  }
   329
   330  int close_connection(h2o_http2_conn_t *conn)
   331  {
   332      conn->state = H2O_HTTP2_CONN_STATE_IS_CLOSING;
   333
   334      if (conn->_write.buf_in_flight != NULL || h2o_timeout_is_linked(&conn->_write.timeout_entry)) {
   335          /* there is a pending write, let on_write_complete actually close the connection */
   336      } else {
   337          close_connection_now(conn);
   338          return -1;
   339      }
   340      return 0;
   341  }
