   343  static void stream_send_error(h2o_http2_conn_t *conn, uint32_t stream_id, int errnum)
   344  {
   345      assert(stream_id != 0);
   346      assert(conn->state < H2O_HTTP2_CONN_STATE_IS_CLOSING);
   347
   348      conn->super.ctx->http2.events.protocol_level_errors[-errnum]++;
   349
   350      h2o_http2_encode_rst_stream_frame(&conn->_write.buf, stream_id, -errnum);
   351      h2o_http2_conn_request_write(conn);
   352  }
   353
   354  static void request_gathered_write(h2o_http2_conn_t *conn)
   355  {
   356      assert(conn->state < H2O_HTTP2_CONN_STATE_IS_CLOSING);
   357      if (conn->sock->_cb.write == NULL && !h2o_timeout_is_linked(&conn->_write.timeout_entry))
   358          h2o_timeout_link(conn->super.ctx->loop, &conn->super.ctx->zero_timeout, &conn->_write.timeout_entry);
   359  }
