   374  static int handle_incoming_request(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream, const uint8_t *src, size_t len,
   375                                     const char **err_desc)
   376  {
   377      int ret, header_exists_map;
   378
   379      assert(stream->state == H2O_HTTP2_STREAM_STATE_RECV_HEADERS);
   380
   381      header_exists_map = 0;
   382      if ((ret = h2o_hpack_parse_headers(&stream->req, &conn->_input_header_table, src, len, &header_exists_map,
   383                                         &stream->req.content_length, &stream->cache_digests, err_desc)) != 0) {
   384          if (ret == H2O_HTTP2_ERROR_INVALID_HEADER_CHAR) {
   385              /* fast forward the stream's state so that we can start sending the response */
   386              h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_REQ_PENDING);
   387              h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_SEND_HEADERS);
   388              h2o_send_error_400(&stream->req, "Invalid Headers", *err_desc, 0);
   389              return 0;
   390          }
   391          return ret;
   392      }
   393
   394  #define EXPECTED_MAP                                                                                                               \
   395      (H2O_HPACK_PARSE_HEADERS_METHOD_EXISTS | H2O_HPACK_PARSE_HEADERS_PATH_EXISTS | H2O_HPACK_PARSE_HEADERS_SCHEME_EXISTS)
   396      if ((header_exists_map & EXPECTED_MAP) != EXPECTED_MAP) {
   397          ret = H2O_HTTP2_ERROR_PROTOCOL;
   398          goto SendRSTStream;
   399      }
   400  #undef EXPECTED_MAP
   401
   402      /* handle the request */
   403      if (conn->num_streams.pull.open > H2O_HTTP2_SETTINGS_HOST.max_concurrent_streams) {
   404          ret = H2O_HTTP2_ERROR_REFUSED_STREAM;
   405          goto SendRSTStream;
   406      }
   407
   408      if (stream->_req_body.body == NULL) {
   409          execute_or_enqueue_request(conn, stream);
   410      } else {
   411          h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_RECV_BODY);
   412      }
   413      return 0;
   414
   415  SendRSTStream:
   416      stream_send_error(conn, stream->stream_id, ret);
   417      h2o_http2_stream_reset(conn, stream);
   418      return 0;
   419  }
   420
   421  static int handle_trailing_headers(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream, const uint8_t *src, size_t len,
   422                                     const char **err_desc)
   423  {
   424      size_t dummy_content_length;
   425      int ret;
   426
   427      if ((ret = h2o_hpack_parse_headers(&stream->req, &conn->_input_header_table, src, len, NULL, &dummy_content_length, NULL,
   428                                         err_desc)) != 0)
   429          return ret;
   430
   431      /* trailing headers for are ignored for streaming body, but
   432         we still need to parse them to keep the HPACK state in sync */
   433      if (!stream->req._write_req_chunk_done) {
   434          assert(stream->state == H2O_HTTP2_STREAM_STATE_RECV_BODY);
   435          execute_or_enqueue_request(conn, stream);
   436      } else {
   437          stream->req._write_req_chunk.cb(stream->req._write_req_chunk.priv, h2o_iovec_init(NULL, 0), 1);
   438      }
   439      return 0;
   440  }
   441
   442  static ssize_t expect_continuation_of_headers(h2o_http2_conn_t *conn, const uint8_t *src, size_t len, const char **err_desc)
   443  {
   444      h2o_http2_frame_t frame;
   445      ssize_t ret;
   446      h2o_http2_stream_t *stream;
   447      int hret;
   448
   449      if ((ret = h2o_http2_decode_frame(&frame, src, len, &H2O_HTTP2_SETTINGS_HOST, err_desc)) < 0)
   450          return ret;
   451      if (frame.type != H2O_HTTP2_FRAME_TYPE_CONTINUATION) {
   452          *err_desc = "expected CONTINUATION frame";
   453          return H2O_HTTP2_ERROR_PROTOCOL;
   454      }
   455
   456      if (conn->state >= H2O_HTTP2_CONN_STATE_HALF_CLOSED)
   457          return 0;
   458
   459      if ((stream = h2o_http2_conn_get_stream(conn, frame.stream_id)) == NULL ||
   460          !(stream->state == H2O_HTTP2_STREAM_STATE_RECV_HEADERS || stream->state == H2O_HTTP2_STREAM_STATE_RECV_BODY)) {
   461          *err_desc = "unexpected stream id in CONTINUATION frame";
   462          return H2O_HTTP2_ERROR_PROTOCOL;
   463      }
   464
   465      if (conn->_headers_unparsed->size + frame.length <= H2O_MAX_REQLEN) {
   466          h2o_buffer_reserve(&conn->_headers_unparsed, frame.length);
   467          memcpy(conn->_headers_unparsed->bytes + conn->_headers_unparsed->size, frame.payload, frame.length);
   468          conn->_headers_unparsed->size += frame.length;
   469
   470          if ((frame.flags & H2O_HTTP2_FRAME_FLAG_END_HEADERS) != 0) {
   471              conn->_read_expect = expect_default;
   472              if (stream->state == H2O_HTTP2_STREAM_STATE_RECV_HEADERS) {
   473                  hret = handle_incoming_request(conn, stream, (const uint8_t *)conn->_headers_unparsed->bytes,
   474                                                 conn->_headers_unparsed->size, err_desc);
   475              } else {
   476                  hret = handle_trailing_headers(conn, stream, (const uint8_t *)conn->_headers_unparsed->bytes,
   477                                                 conn->_headers_unparsed->size, err_desc);
   478              }
   479              if (hret != 0)
   480                  ret = hret;
   481              h2o_buffer_dispose(&conn->_headers_unparsed);
   482              conn->_headers_unparsed = NULL;
   483          }
   484      } else {
   485          /* request is too large (TODO log) */
   486          stream_send_error(conn, stream->stream_id, H2O_HTTP2_ERROR_REFUSED_STREAM);
   487          h2o_http2_stream_reset(conn, stream);
   488      }
   489
   490      return ret;
   491  }
   492
   493  static void update_input_window(h2o_http2_conn_t *conn, uint32_t stream_id, h2o_http2_window_t *window, size_t consumed)
   494  {
   495      h2o_http2_window_consume_window(window, consumed);
   496      if (h2o_http2_window_get_window(window) * 2 < H2O_HTTP2_SETTINGS_HOST.initial_window_size) {
   497          int32_t delta = (int32_t)(H2O_HTTP2_SETTINGS_HOST.initial_window_size - h2o_http2_window_get_window(window));
   498          h2o_http2_encode_window_update_frame(&conn->_write.buf, stream_id, delta);
   499          h2o_http2_conn_request_write(conn);
   500          h2o_http2_window_update(window, delta);
   501      }
   502  }
   503
   504  static void set_priority(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream, const h2o_http2_priority_t *priority,
   505                           int scheduler_is_open)
   506  {
   507      h2o_http2_scheduler_node_t *parent_sched;
   508
   509      /* determine the parent */
   510      if (priority->dependency != 0) {
   511          h2o_http2_stream_t *parent_stream = h2o_http2_conn_get_stream(conn, priority->dependency);
   512          if (parent_stream != NULL) {
   513              parent_sched = &parent_stream->_refs.scheduler.node;
   514          } else {
   515              /* A dependency on a stream that is not currently in the tree - such as a stream in the "idle" state - results in that
   516               * stream being given a default priority. (RFC 7540 5.3.1)
   517               * It is possible for a stream to become closed while prioritization information that creates a dependency on that
   518               * stream is in transit. If a stream identified in a dependency has no associated priority information, then the
   519               * dependent stream is instead assigned a default priority. (RFC 7540 5.3.4)
   520               */
   521              parent_sched = &conn->scheduler;
   522              priority = &h2o_http2_default_priority;
   523          }
   524      } else {
   525          parent_sched = &conn->scheduler;
   526      }
   527
   528      /* setup the scheduler */
   529      if (!scheduler_is_open) {
   530          h2o_http2_scheduler_open(&stream->_refs.scheduler, parent_sched, priority->weight, priority->exclusive);
   531      } else {
   532          h2o_http2_scheduler_rebind(&stream->_refs.scheduler, parent_sched, priority->weight, priority->exclusive);
   533      }
   534  }
   535
   536  static void write_req_chunk_done(h2o_req_t *req, size_t written, int done)
   537  {
   538      h2o_http2_stream_t *stream = H2O_STRUCT_FROM_MEMBER(h2o_http2_stream_t, req, req);
   539      h2o_http2_conn_t *conn = (h2o_http2_conn_t *)stream->req.conn;
   540
   541      if (stream->request_blocked_by_server) {
   542          h2o_http2_stream_set_request_blocked_by_server(conn, stream, 0);
   543          update_idle_timeout(conn);
   544      }
   545
   546      update_input_window(conn, stream->stream_id, &stream->input_window, written);
   547
   548      if (done) {
   549          if (stream->state == H2O_HTTP2_STREAM_STATE_RECV_BODY) {
   550              h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_REQ_PENDING);
   551              h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_SEND_HEADERS);
   552          }
   553          run_pending_requests(conn);
   554      }
   555  }
   556
   557  static int write_req_chunk(void *req_, h2o_iovec_t payload, int is_end_stream)
   558  {
   559      h2o_req_t *req = req_;
   560      h2o_http2_stream_t *stream = H2O_STRUCT_FROM_MEMBER(h2o_http2_stream_t, req, req);
   561      h2o_http2_conn_t *conn = (h2o_http2_conn_t *)stream->req.conn;
   562
   563      if (h2o_buffer_append(&stream->_req_body.body, payload.base, payload.len) == 0)
   564          return -1;
   565      stream->req.entity = h2o_iovec_init(stream->_req_body.body->bytes, stream->_req_body.body->size);
   566
   567      /* handle request if request body is complete */
   568      if (!stream->req._write_req_chunk_done) {
   569          if (is_end_stream) {
   570              stream->req.entity = h2o_iovec_init(stream->_req_body.body->bytes, stream->_req_body.body->size);
   571              execute_or_enqueue_request(conn, stream);
   572          } else {
   573              if (!stream->req._found_handler) {
   574                  stream->req._found_handler = 1;
   575                  h2o_handler_t *h = h2o_get_first_handler(&stream->req);
   576                  if (h != NULL && h->has_body_stream) {
   577                      stream->req._write_req_chunk_done = write_req_chunk_done;
   578                      stream->_req_body.streamed_body_size = stream->_req_body.body->size;
   579                      execute_or_enqueue_request(conn, stream);
   580                  }
   581              } else {
   582                  write_req_chunk_done(req, payload.len, is_end_stream);
   583              }
   584          }
   585      } else {
   586          if (is_end_stream) {
   587              stream->req._write_req_chunk_done = NULL;
   588              stream->req._write_req_chunk.cb = NULL;
   589          }
   590      }
   591
   592      return 0;
   593  }
   594
   595  static int handle_data_frame(h2o_http2_conn_t *conn, h2o_http2_frame_t *frame, const char **err_desc)
   596  {
   597      h2o_http2_data_payload_t payload;
   598      h2o_http2_stream_t *stream;
   599      int ret;
   600
   601      if ((ret = h2o_http2_decode_data_payload(&payload, frame, err_desc)) != 0)
   602          return ret;
   603
   604      if (conn->state >= H2O_HTTP2_CONN_STATE_HALF_CLOSED)
   605          return 0;
   606
   607      update_input_window(conn, 0, &conn->_input_window, payload.length);
   608
   609      stream = h2o_http2_conn_get_stream(conn, frame->stream_id);
   610
   611      /* save the input in the request body buffer, or send error (and close the stream) */
   612      if (stream == NULL) {
   613          if (frame->stream_id <= conn->pull_stream_ids.max_open) {
   614              stream_send_error(conn, frame->stream_id, H2O_HTTP2_ERROR_STREAM_CLOSED);
   615              stream = NULL;
   616          } else {
   617              *err_desc = "invalid DATA frame";
   618              return H2O_HTTP2_ERROR_PROTOCOL;
   619          }
   620      } else if (stream->state != H2O_HTTP2_STREAM_STATE_RECV_BODY) {
   621          stream_send_error(conn, frame->stream_id, H2O_HTTP2_ERROR_STREAM_CLOSED);
   622          h2o_http2_stream_reset(conn, stream);
   623          stream = NULL;
   624      } else if (h2o_http2_stream_req_body_size(stream) + payload.length > conn->super.ctx->globalconf->max_request_entity_size) {
   625          stream_send_error(conn, frame->stream_id, H2O_HTTP2_ERROR_REFUSED_STREAM);
   626          h2o_http2_stream_reset(conn, stream);
   627          stream = NULL;
   628      } else {
   629          int ret;
   630
   631          if (!stream->request_blocked_by_server) {
   632              h2o_http2_stream_set_request_blocked_by_server(conn, stream, 1);
   633              update_idle_timeout(conn);
   634          }
   635
   636          ret = stream->req._write_req_chunk.cb(stream->req._write_req_chunk.priv, h2o_iovec_init(payload.data, payload.length),
   637                                                frame->flags & H2O_HTTP2_FRAME_FLAG_END_STREAM);
   638          if (ret < 0) {
   639              stream_send_error(conn, frame->stream_id, H2O_HTTP2_ERROR_STREAM_CLOSED);
   640              h2o_http2_stream_reset(conn, stream);
   641              stream = NULL;
   642              goto UpdateWindow;
   643          }
   644          return 0;
   645      }
   646
   647  UpdateWindow:
   648      /* consume buffer (and set window_update) */
   649      update_input_window(conn, 0, &conn->_input_window, frame->length);
   650      if (stream != NULL)
   651          update_input_window(conn, stream->stream_id, &stream->input_window, frame->length);
   652
   653      return 0;
   654  }
   655
   656  static int handle_headers_frame(h2o_http2_conn_t *conn, h2o_http2_frame_t *frame, const char **err_desc)
   657  {
   658      h2o_http2_headers_payload_t payload;
