   381  void h2o_http2_stream_send_pending_data(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream)
   382  {
   383      if (h2o_http2_window_get_window(&stream->output_window) <= 0)
   384          return;
   385
   386      if (stream->_pull_cb != NULL) {
   387          h2o_send_state_t send_state;
   388          /* pull mode */
   389          assert(stream->state != H2O_HTTP2_STREAM_STATE_END_STREAM);
   390          send_state = send_data_pull(conn, stream);
   391          if (send_state != H2O_SEND_STATE_IN_PROGRESS) {
   392              /* sent all data */
   393              stream->_data.size = 0;
   394              h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_END_STREAM);
   395          }
   396      } else {
   397          /* push mode */
   398          h2o_iovec_t *nextbuf = send_data_push(conn, stream, stream->_data.entries, stream->_data.size, stream->send_state);
   399          if (nextbuf == stream->_data.entries + stream->_data.size) {
   400              /* sent all data */
   401              stream->_data.size = 0;
   402              if (stream->state == H2O_HTTP2_STREAM_STATE_SEND_BODY_IS_FINAL)
   403                  h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_END_STREAM);
   404          } else if (nextbuf != stream->_data.entries) {
   405              /* adjust the buffer */
   406              size_t newsize = stream->_data.size - (nextbuf - stream->_data.entries);
   407              memmove(stream->_data.entries, nextbuf, sizeof(h2o_iovec_t) * newsize);
   408              stream->_data.size = newsize;
   409          }
   410      }
   411  }
