   421  static int handle_trailing_headers(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream, const uint8_t *src, size_t len,
   422                                     const char **err_desc)
   423  {
   424      size_t dummy_content_length;
   425      int ret;
   426
   427      if ((ret = h2o_hpack_parse_headers(&stream->req, &conn->_input_header_table, src, len, NULL, &dummy_content_length, NULL,
   428                                         err_desc)) != 0)
   429          return ret;
   430
   431      /* trailing headers for are ignored for streaming body, but
   432         we still need to parse them to keep the HPACK state in sync */
   433      if (!stream->req._write_req_chunk_done) {
   434          assert(stream->state == H2O_HTTP2_STREAM_STATE_RECV_BODY);
   435          execute_or_enqueue_request(conn, stream);
   436      } else {
   437          stream->req._write_req_chunk.cb(stream->req._write_req_chunk.priv, h2o_iovec_init(NULL, 0), 1);
   438      }
   439      return 0;
   440  }
