   504  static void set_priority(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream, const h2o_http2_priority_t *priority,
   505                           int scheduler_is_open)
   506  {
   507      h2o_http2_scheduler_node_t *parent_sched;
   508
   509      /* determine the parent */
   510      if (priority->dependency != 0) {
   511          h2o_http2_stream_t *parent_stream = h2o_http2_conn_get_stream(conn, priority->dependency);
   512          if (parent_stream != NULL) {
   513              parent_sched = &parent_stream->_refs.scheduler.node;
   514          } else {
   515              /* A dependency on a stream that is not currently in the tree - such as a stream in the "idle" state - results in that
   516               * stream being given a default priority. (RFC 7540 5.3.1)
   517               * It is possible for a stream to become closed while prioritization information that creates a dependency on that
   518               * stream is in transit. If a stream identified in a dependency has no associated priority information, then the
   519               * dependent stream is instead assigned a default priority. (RFC 7540 5.3.4)
   520               */
   521              parent_sched = &conn->scheduler;
   522              priority = &h2o_http2_default_priority;
   523          }
   524      } else {
   525          parent_sched = &conn->scheduler;
   526      }
   527
   528      /* setup the scheduler */
   529      if (!scheduler_is_open) {
   530          h2o_http2_scheduler_open(&stream->_refs.scheduler, parent_sched, priority->weight, priority->exclusive);
   531      } else {
   532          h2o_http2_scheduler_rebind(&stream->_refs.scheduler, parent_sched, priority->weight, priority->exclusive);
   533      }
   534  }
